import{_ as s,I as t,o as r,c as d,b6 as e,j as h,J as i,w as o}from"./chunks/framework.COUcLbTA.js";const P=JSON.parse('{"title":"智能旅游规划 Agent 平台开发实战","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/stage-2/assignments/travel-planning-agent-platform/index.md","filePath":"zh-cn/stage-2/assignments/travel-planning-agent-platform/index.md"}'),p={name:"zh-cn/stage-2/assignments/travel-planning-agent-platform/index.md"},c={style:{margin:"32px 0"}};function b(g,a,k,u,m,f){const l=t("StepBar"),n=t("ClientOnly");return r(),d("div",null,[a[0]||(a[0]=e('<h1 id="智能旅游规划-agent-平台开发实战" tabindex="-1">智能旅游规划 Agent 平台开发实战 <a class="header-anchor" href="#智能旅游规划-agent-平台开发实战" aria-label="Permalink to “智能旅游规划 Agent 平台开发实战”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>本实战项目要求你围绕一份真实的 PRD，从零完成一个智能旅游规划 Agent 平台。你将构建一个能接收结构化输入、生成每日行程、支持保存和重用的完整 AI 产品——不只是聊天机器人，而是一个有任务管理能力的产品。</p><p>这是 Stage 2 的综合实战环节。这个项目的核心挑战在于：如何让 AI 生成结构化、可用的行程规划，而不是一大段不可操作的文字。</p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to “前置知识”">​</a></h2><p>在开始本项目之前，你应该已经掌握以下内容：</p><ul><li>前端页面设计与组件库使用（<a href="./../../frontend/ui-design/">UI 设计</a>、<a href="./../../frontend/modern-component-library/">现代组件库</a>）</li><li>后端接口设计与开发（<a href="./../../backend/ai-interface-code/">接口代码编写</a>）</li><li>数据库基础与 Supabase（<a href="./../../backend/database-supabase/">从数据库到 Supabase</a>）</li><li>Git 工作流与部署（<a href="./../../backend/git-workflow/">Git 和 GitHub</a>、<a href="./../../backend/zeabur-deployment/">部署 Web 应用</a>）</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to “学习目标”">​</a></h2><p>完成本实战后，你将能够：</p><ol><li>阅读 PRD 并从中提取 Agent 平台的开发任务清单</li><li>设计结构化的输入表单和结构化的输出格式</li><li>实现 Agent 编排层，处理用户输入、模型调用和结果存储</li><li>构建&quot;生成 → 保存 → 重用&quot;的业务闭环</li><li>完成端到端联调，交付可演示的 AI 产品原型</li></ol><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to “项目简介”">​</a></h2><p>你要构建的产品是一个智能旅游规划 Agent 平台：</p><table tabindex="0"><thead><tr><th>功能</th><th>描述</th></tr></thead><tbody><tr><td><strong>行程规划</strong></td><td>用户输入出发地、目的地、日期、预算和偏好，系统生成每日行程</td></tr><tr><td><strong>预算拆分</strong></td><td>行程结果包含预算分配和建议</td></tr><tr><td><strong>历史管理</strong></td><td>用户可以保存历史计划、再次生成、导出</td></tr><tr><td><strong>管理后台</strong></td><td>管理员查看热门目的地、失败任务和用户反馈</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本项目的需求文档在 GitHub： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/travel-planning-agent-platform/PRD.md" target="_blank" rel="noreferrer">查看 PRD</a></p></div>',14)),h("div",c,[i(n,null,{default:o(()=>[i(l,{active:0,items:[{title:"需求分析",description:"阅读 PRD，明确页面、Agent 编排、输入输出结构"},{title:"搭建骨架",description:"用 AI 生成首页、规划页、历史页、后台页骨架"},{title:"迭代开发",description:"逐模块补充结构化输出、任务状态、历史管理"},{title:"联调上线",description:"端到端跑通，部署并准备演示"}]})]),_:1})]),a[1]||(a[1]=e(`<h2 id="第一部分-需求分析" tabindex="-1">第一部分：需求分析 <a class="header-anchor" href="#第一部分-需求分析" aria-label="Permalink to “第一部分：需求分析”">​</a></h2><h3 id="_1-1-阅读-prd" tabindex="-1">1.1 阅读 PRD <a class="header-anchor" href="#_1-1-阅读-prd" aria-label="Permalink to “1.1 阅读 PRD”">​</a></h3><p>打开 PRD 文档，重点回答以下问题：</p><ul><li>第一版是否只做单目的地？</li><li>行程输出是否必须结构化？结构是什么？</li><li>导出能力做多深？（分享链接 / PDF / 图片）</li><li>后台统计和任务日志的范围是什么？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>如果以上问题没有明确答案，不要开始写代码。需求理解不清楚是导致返工的最常见原因。</p></div><h3 id="_1-2-确认系统架构" tabindex="-1">1.2 确认系统架构 <a class="header-anchor" href="#_1-2-确认系统架构" aria-label="Permalink to “1.2 确认系统架构”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; planner[&quot;规划页&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  planner --&gt; agent[&quot;Agent 编排层&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agent --&gt; model[&quot;模型调用&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  agent --&gt; db[&quot;数据库&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  db --&gt; history[&quot;历史计划&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  db --&gt; admin[&quot;后台统计与日志&quot;]</span></span></code></pre></div><h2 id="第二部分-搭建项目骨架" tabindex="-1">第二部分：搭建项目骨架 <a class="header-anchor" href="#第二部分-搭建项目骨架" aria-label="Permalink to “第二部分：搭建项目骨架”">​</a></h2><h3 id="_2-1-生成前端页面" tabindex="-1">2.1 生成前端页面 <a class="header-anchor" href="#_2-1-生成前端页面" aria-label="Permalink to “2.1 生成前端页面”">​</a></h3><p>提示词参考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请基于当前 PRD，帮我生成一个智能旅游规划 Agent 平台的前端骨架。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 页面包括：首页、规划页、行程详情页、历史记录页、管理页</span></span>
<span class="line"><span>2. 规划页左侧是表单，右侧是结果预览</span></span>
<span class="line"><span>3. 先只生成页面结构和假数据，不接真实接口</span></span>
<span class="line"><span>4. 风格要像现代 AI 产品</span></span></code></pre></div><h3 id="_2-2-验证页面结构" tabindex="-1">2.2 验证页面结构 <a class="header-anchor" href="#_2-2-验证页面结构" aria-label="Permalink to “2.2 验证页面结构”">​</a></h3><p>逐项检查：</p><ul><li>[ ] 规划页的表单字段是否与 PRD 一致</li><li>[ ] 结果预览区域能展示结构化的行程数据</li><li>[ ] 历史记录页可以展示多条计划</li><li>[ ] 管理后台页可以展示统计数据</li></ul><h2 id="第三部分-迭代开发" tabindex="-1">第三部分：迭代开发 <a class="header-anchor" href="#第三部分-迭代开发" aria-label="Permalink to “第三部分：迭代开发”">​</a></h2><h3 id="_3-1-按模块推进" tabindex="-1">3.1 按模块推进 <a class="header-anchor" href="#_3-1-按模块推进" aria-label="Permalink to “3.1 按模块推进”">​</a></h3><ol><li><strong>鉴权</strong>：注册、登录</li><li><strong>规划表单</strong>：结构化输入（出发地、目的地、日期、预算、偏好）</li><li><strong>Agent 编排</strong>：接收输入 → 调用模型 → 解析结构化输出</li><li><strong>结果展示</strong>：行程按天展示、预算拆分、建议</li><li><strong>历史管理</strong>：保存计划、再次生成、导出</li><li><strong>管理后台</strong>：热门目的地、失败任务、用户反馈</li><li><strong>任务状态</strong>：生成中 / 成功 / 失败的状态管理和错误记录</li></ol><h3 id="_3-2-模块自检" tabindex="-1">3.2 模块自检 <a class="header-anchor" href="#_3-2-模块自检" aria-label="Permalink to “3.2 模块自检”">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>验证方法</th></tr></thead><tbody><tr><td>输入完整性</td><td>表单字段是否与 PRD 一致</td></tr><tr><td>输出结构化</td><td>行程结果是不是结构化数据（而非一大段文字）</td></tr><tr><td>数据一致性</td><td>trip、itinerary、logs 数据是否对得上</td></tr><tr><td>闭环验证</td><td>是否能演示&quot;输入 → 生成 → 保存 → 再次生成&quot;</td></tr></tbody></table><h2 id="第四部分-联调与上线" tabindex="-1">第四部分：联调与上线 <a class="header-anchor" href="#第四部分-联调与上线" aria-label="Permalink to “第四部分：联调与上线”">​</a></h2><h3 id="_4-1-端到端测试" tabindex="-1">4.1 端到端测试 <a class="header-anchor" href="#_4-1-端到端测试" aria-label="Permalink to “4.1 端到端测试”">​</a></h3><p>至少验证以下场景：</p><ul><li>输入行程参数 → 生成每日行程 → 查看预算拆分 → 保存到历史</li><li>从历史记录中再次生成行程</li><li>管理员查看任务统计和失败日志</li></ul><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to “交付物”">​</a></h2><p>完成本项目后，你需要提交以下内容：</p><ul><li>[ ] 可访问的线上演示链接</li><li>[ ] 源码仓库链接（含 README）</li><li>[ ] PRD 文档</li><li>[ ] 核心页面截图（规划页、行程详情页、历史记录页、管理后台）</li><li>[ ] 60 秒演示视频</li></ul><h2 id="评分标准" tabindex="-1">评分标准 <a class="header-anchor" href="#评分标准" aria-label="Permalink to “评分标准”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>基本要求</th><th>进阶要求</th></tr></thead><tbody><tr><td>PRD 对齐</td><td>页面、功能、数据结构基本符合 PRD</td><td>能清晰说明设计决策</td></tr><tr><td>产品闭环</td><td>规划 → 保存 → 历史 → 重生成可跑通</td><td>支持导出和分享</td></tr><tr><td>输出质量</td><td>行程结果结构化且可读</td><td>预算拆分合理、建议有针对性</td></tr><tr><td>后台能力</td><td>任务统计和失败日志可查看</td><td>有热门目的地分析</td></tr><tr><td>工程完整度</td><td>前端、后端、数据库、模型调用链路已接通</td><td>任务状态管理完善，错误可追溯</td></tr></tbody></table><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to “参考资料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 设计</a></li><li><a href="./../../frontend/modern-component-library/">使用现代组件库更新你的界面</a></li><li><a href="./../../backend/database-supabase/">从数据库到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">大模型辅助编写接口代码与接口文档</a></li><li><a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a></li><li><a href="./../../backend/zeabur-deployment/">如何部署 Web 应用</a></li></ul>`,30))])}const x=s(p,[["render",b]]);export{P as __pageData,x as default};
